public class DocTagExtractorTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        String full = "/**\n"
                + " * Clamps a value into a range.\n"
                + " *\n"
                + " * @param value the input\n"
                + " * @param low the floor\n"
                + " * @param high the ceiling\n"
                + " * @return the clamped value\n"
                + " * @throws IllegalArgumentException when low is bigger than high\n"
                + " * @exception IllegalStateException when the range is closed\n"
                + " */";
        String noReturn = "/** Resets the counter.\n"
                + " * @param reason why the reset happened\n"
                + " */";
        String bareReturn = "/**\n"
                + " * Reports the size.\n"
                + " * @return\n"
                + " */";

        check("param names in order", "[value, low, high]",
                DocTagExtractor.paramNames(full).toString());
        check("return tag found", true, DocTagExtractor.hasReturnTag(full));
        check("throws and exception both count", "[IllegalArgumentException, IllegalStateException]",
                DocTagExtractor.thrownTypes(full).toString());
        check("single param on a one line comment", "[reason]",
                DocTagExtractor.paramNames(noReturn).toString());
        check("no return tag", false, DocTagExtractor.hasReturnTag(noReturn));
        check("bare return tag counts", true, DocTagExtractor.hasReturnTag(bareReturn));
        check("no throws tags", "[]", DocTagExtractor.thrownTypes(noReturn).toString());
        check("null comment", "[]", DocTagExtractor.paramNames(null).toString());
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

