public class DocTagExtractor {

    public static java.util.List<String> paramNames(String docComment) {
        return namesAfter(docComment, "@param");
    }

    public static boolean hasReturnTag(String docComment) {
        if (docComment == null) {
            return false;
        }
        for (String raw : docComment.split("\n", -1)) {
            String line = clean(raw);
            if (line.equals("@return") || line.startsWith("@return ")) {
                return true;
            }
        }
        return false;
    }

    public static java.util.List<String> thrownTypes(String docComment) {
        java.util.List<String> types = namesAfter(docComment, "@throws");
        types.addAll(namesAfter(docComment, "@exception"));
        return types;
    }

    private static java.util.List<String> namesAfter(String docComment, String tag) {
        java.util.List<String> names = new java.util.ArrayList<>();
        if (docComment == null) {
            return names;
        }
        for (String raw : docComment.split("\n", -1)) {
            String line = clean(raw);
            if (!line.startsWith(tag + " ")) {
                continue;
            }
            String rest = line.substring(tag.length()).trim();
            int space = rest.indexOf(' ');
            names.add(space < 0 ? rest : rest.substring(0, space));
        }
        return names;
    }

    private static String clean(String raw) {
        String line = raw.trim();
        if (line.startsWith("/**")) {
            line = line.substring(3).trim();
        } else if (line.startsWith("*")) {
            line = line.substring(1).trim();
        }
        return line;
    }
}
